message.content:
{
  "description": "The creature is shown in right-facing side profile against a plain off-white background, standing low to the ground on four short limbs. It has a pale pink, fleshy axolotl-like head, underbelly, and legs with wrinkled skin, and a continuous covering of large, overlapping dark brown to grayish scales with lighter tan edges over its back, sides, and long tail. The head is broad and rounded with large dark eyes, small nostrils, and a slightly upturned mouth, with dark speckling on the dorsal surface. Six pink, feathery external gill stalks with fine filaments protrude from the sides of the neck just behind the head. The body is elongated and robust, the tail is long, thick at the base and tapering toward the left edge of the image, scaled on top and pale and ridged underneath. The four limbs are stout and end in clawed, five-toed feet.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, rounded and pale pink with a lighter muzzle, small round nostril, large dark eye with a glossy black pupil and light blue-gray iris, and a faint closed-mouth line giving a slight smile; dark gray speckles on the top and side of the head",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "gills",
      "looks_like": "six pink stalk-like external gills with dense, feathery red-pink filaments along each stalk; three stalks visible on the near side of the neck projecting outward and three stalks visible on the far side projecting upward behind the head",
      "where": "clustered on both sides of the neck immediately behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, columnar limbs with wrinkled pale pink skin and visible folds at the joints",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, fleshy feet with five short digits each tipped with small dark curved claws; skin is wrinkled and pale pink with darker shading between toes",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, tapering tail; dorsal and lateral surfaces covered in overlapping scales, ventral surface is pale pink with transverse ridged wrinkles",
      "where": "extending leftward from the rear of the body, tapering to a point out of full view on the left"
    },
    {
      "part": "plates",
      "looks_like": "large, overlapping keratinous plates with a rounded, scale-like shape, dark brown-gray centers with lighter tan-brown edges and fine concentric ridges",
      "where": "covering the entire dorsal surface from the back of the neck over the back and onto the top of the tail in diagonal rows"
    },
    {
      "part": "scales",
      "looks_like": "same as plates - overlapping, hard-looking scales forming a continuous armor",
      "where": "dorsal back, sides, and tail top"
    },
    {
      "part": "markings",
      "looks_like": "small irregular dark gray-brown spots and speckles",
      "where": "scattered on the top and side of the head around the eye and gill bases"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
